export function parsePPRatio(blend) {
  if (!blend || blend === 'Non') return null;
  const m = String(blend).match(/^(\d+(?:\.\d+)?)/);
  return m ? Number(m[1]) : null;
}

export function isComposite(blend) {
  return Boolean(blend && blend !== 'Non');
}
